{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split.json
    A split hero: a badge, the heading, a lead, an extra under it and one or two actions, beside the media. Axes: extra (stats: three figures, avatars: faces and a proof line, minis: two small feature cards, quote: a quote over three figures, none), media (picture, card: a floating card on the picture, grid: four pictures with captions, plans: two plan cards on the picture), mediaSide, tone.
    Props (p): id, title, lead, badge, level, actions, content, extra, media, mediaSide, tone, landmarkLabel. -#}
{%- set v_id = ui_def(p['id'], none) -%}
{%- set v_title = ui_def(p['title'], none) -%}
{%- set v_lead = ui_def(p['lead'], '') -%}
{%- set v_badge = ui_def(p['badge'], '') -%}
{%- set v_level = ui_def(p['level'], 1) -%}
{%- set v_actions = ui_def(p['actions'], none) -%}
{%- set v_content = ui_def(p['content'], none) -%}
{%- set v_extra = ui_def(p['extra'], 'stats') -%}
{%- set v_media = ui_def(p['media'], 'picture') -%}
{%- set v_mediaSide = ui_def(p['mediaSide'], 'end') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_landmarkLabel = ui_def(p['landmarkLabel'], none) -%}
{%- set f_1 -%}
  {{ ui_include('blocks/hero-split-media.html.j2', {'p': {'content': v_content, 'alt': v_title, 'media': v_media}}) }}
{%- endset -%}
{%- set c_2 -%}
  {{ ui_include('blocks/hero-split-extras.html.j2', {'p': {'content': v_content, 'extra': v_extra}}) }}
  {{ ui_include('blocks/action-group.html.j2', {'p': {'primary': ui_get(v_actions, ['cta']), 'primaryHref': ui_get(v_actions, ['href']), 'secondary': (ui_get(v_actions, ['secondary']) if ui_t(ui_eq(ui_get(v_actions, ['mode']), 'two')) else none), 'secondaryHref': ui_get(v_actions, ['secondaryHref'])}}) }}
{%- endset -%}
